 geometry.append({'path':asset['path'],'origin_pixels':origin,'pi_pixels':sx,'unit_y_pixels':sy,'blue_extent_pixels':[int(xs.min()),int(xs.max()),int(ys.min()),int(ys.max())],'vertex_checks':checks,'dpi':Image.open(asset['path']).info.get('dpi'),'measurement':'direct palette-decoded source raster; bounded 2.5px stroke/antialias allowance; no white label masks'})
